<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, Download, ArrowRight } from '@element-plus/icons-vue'
import { api, exportCsv } from '../api'
import { state, refresh, vehicle, customer, branch, rule, labels, money, dateText, localTime, netPaid, payments, overdue } from '../store'
import { matchesOrderScope } from '../dashboard'
import StatusTag from '../components/StatusTag.vue'
import VehicleThumbnail from '../components/VehicleThumbnail.vue'
import FormDialog from '../components/FormDialog.vue'
const route = useRoute(), router = useRouter(), query = reactive({ search: '', status: route.query.status || '', scope: route.query.scope || '' }), page = ref(1), detailId = ref(null), open = ref(false), editId = ref(null), busy = ref(false), formRef = ref(null), quote = ref(null), quoteError = ref(''), actionOpen = ref(false), actionType = ref(''), actionInitial = ref({})
const form = reactive({})
const detail = computed(() => state.orders.find(order => order.id === detailId.value))
const filtered = computed(() => state.orders.filter(order => matchesOrderScope(order, query.scope) && (!query.status || order.status === query.status) && (!query.search || `${order.order_no}${customer(order.customer_id).name}${vehicle(order.vehicle_id).plate}`.toLowerCase().includes(query.search.toLowerCase()))))
watch(query, () => page.value = 1)
watch(() => route.query.status, value => query.status = value || '')
watch(() => route.query.scope, value => query.scope = value || '')
watch(() => route.query.detail, value => { if (value) detailId.value = Number(value) })
const formRules = Object.fromEntries(['customer_id', 'vehicle_id', 'planned_start', 'planned_end', 'billing_mode', 'pickup_branch', 'return_branch', 'expected_mileage'].map(key => [key, [{ required: true, message: '请完整填写此项', trigger: ['blur', 'change'] }]]))
function create(order) {
  editId.value = order?.id || null
  Object.keys(form).forEach(key => delete form[key])
  Object.assign(form, order ? { ...order } : { customer_id: undefined, vehicle_id: Number(route.query.vehicle) || undefined, planned_start: localTime(new Date(Date.now() + 60000)), planned_end: localTime(new Date(Date.now() + 86460000)), billing_mode: 'DAILY', expected_mileage: 200, pickup_branch: state.branches[0]?.id, return_branch: state.branches[0]?.id })
  if (form.vehicle_id) { form.pickup_branch = vehicle(form.vehicle_id).branch_id; if (!order) form.return_branch = form.pickup_branch }
  quote.value = null; quoteError.value = ''; open.value = true
}
onMounted(() => { if (route.query.create) create(); if (route.query.detail) detailId.value = Number(route.query.detail) })
watch(() => route.query.create, value => { if (value) create() })
function carChanged(id) { form.pickup_branch = vehicle(id).branch_id; form.return_branch = form.pickup_branch }
function canBook(car) {
  if (!['AVAILABLE', 'RENTED'].includes(car.status)) return false
  if (!form.planned_start || !form.planned_end) return true
  return !state.orders.some(order => order.vehicle_id === car.id && order.id !== editId.value && ['RESERVED', 'ACTIVE'].includes(order.status) && (overdue(order) || (form.planned_start < order.planned_end && form.planned_end > order.planned_start))) && !state.dispatch.some(task => task.vehicle_id === car.id && ['PENDING', 'IN_PROGRESS'].includes(task.status) && form.planned_start < task.planned_end && form.planned_end > task.planned_start)
}
let quoteTimer, quoteVersion = 0
watch(() => [form.vehicle_id, form.planned_start, form.planned_end, form.billing_mode, form.expected_mileage], () => {
  clearTimeout(quoteTimer); const version = ++quoteVersion
  if (!open.value || !form.vehicle_id || !form.planned_start || !form.planned_end) return
  quoteTimer = setTimeout(async () => { try { const result = await api.post('/pricing/quote', form, { silent: true }); if (version === quoteVersion) { quote.value = result; quoteError.value = '' } } catch (error) { if (version === quoteVersion) { quote.value = null; quoteError.value = error.response?.data?.message || '暂时无法报价' } } }, 200)
}, { flush: 'post' })
async function save() {
  if (!await formRef.value.validate().catch(() => false)) return
  busy.value = true
  try { const result = await api[editId.value ? 'put' : 'post']('/orders' + (editId.value ? '/' + editId.value : ''), form); open.value = false; await refresh(); detailId.value = result.id; router.replace('/orders'); ElMessage.success('租赁订单已保存') } catch {} finally { busy.value = false }
}
const actionFields = computed(() => {
  if (actionType.value === 'collect') return [{ key: 'kind', label: '款项类型', type: 'select', options: [{ label: '押金', value: 'DEPOSIT' }, { label: '预收租金', value: 'RENT' }], wide: true }, { key: 'amount', label: '实际收款金额（元）', type: 'number', precision: 2, min: 0.01, wide: true, tip: '仅登记已经实际收到的线下款项' }]
  if (actionType.value === 'pickup') return [{ key: 'start_mileage', label: '取车里程（km）', type: 'number', min: Number(vehicle(detail.value?.vehicle_id).mileage || 0), wide: true }, { key: 'condition', label: '交车车况', type: 'textarea', wide: true, maxlength: 500, tip: '交车时间由系统记录为实际办理时间' }]
  return [{ key: 'end_mileage', label: '还车里程（km）', type: 'number', min: Number(detail.value?.start_mileage || 0) }, { key: 'return_branch', label: '实际还车门店', type: 'select', options: state.branches.map(item => ({ label: item.name, value: item.id })) }, { key: 'extra_fee', label: '附加费用（元）', type: 'number', precision: 2 }, { key: 'discount', label: '优惠金额（元）', type: 'number', precision: 2 }, { key: 'fee_notes', label: '附加费用明细', type: 'textarea', required: false, wide: true, maxlength: 500, tip: '附加费用大于零时必填，请逐项说明' }, { key: 'condition', label: '还车车况', type: 'textarea', wide: true, maxlength: 450 }, { key: 'damage', label: '发现损坏，转入维修', type: 'switch', required: false, wide: true }]
})
function act(type) {
  actionType.value = type
  const order = detail.value
  const depositPaid = payments(order.id).filter(item => item.kind === 'DEPOSIT').reduce((total, item) => total + Number(item.amount), 0)
  actionInitial.value = type === 'collect' ? { kind: 'DEPOSIT', amount: Math.max(0, Number(order.deposit) - depositPaid) } : type === 'pickup' ? { start_mileage: Number(vehicle(order.vehicle_id).mileage), condition: '车况正常，随车物品齐全' } : { end_mileage: Number(order.start_mileage), return_branch: order.return_branch, extra_fee: 0, discount: 0, fee_notes: '', condition: '验收正常', damage: false }
  actionOpen.value = true
}
async function submitAction(data) {
  busy.value = true
  try { await api.post(`/orders/${detail.value.id}/${actionType.value}`, { ...data, request_id: crypto.randomUUID() }); actionOpen.value = false; await refresh(); ElMessage.success('业务办理成功') } catch {} finally { busy.value = false }
}
async function terminal(type) {
  const order = detail.value
  const difference = type === 'cancel' ? -netPaid(order.id) : Number(order.actual_rent) - netPaid(order.id)
  const text = difference > 0 ? `本次需补收 ¥${money(difference)}` : difference < 0 ? `本次需退款 ¥${money(-difference)}` : '本次无需补款或退款'
  try { await ElMessageBox.confirm(`${text}。请确认线下收退款已处理，再${type === 'cancel' ? '取消订单' : '完成结算'}。`, type === 'cancel' ? '取消订单并退款' : '确认结算', { confirmButtonText: '已处理，确认', type: 'warning' }); busy.value = true; await api.post(`/orders/${order.id}/${type}`, { request_id: crypto.randomUUID() }); await refresh(); ElMessage.success(type === 'cancel' ? '订单已取消' : '订单已完成结算') } catch {} finally { busy.value = false }
}
function exportData() { exportCsv(filtered.value, [{ label: '订单号', value: 'order_no' }, { label: '客户', value: row => customer(row.customer_id).name }, { label: '车辆', value: row => vehicle(row.vehicle_id).plate }, { label: '计划取车', value: row => dateText(row.planned_start) }, { label: '计划还车', value: row => dateText(row.planned_end) }, { label: '预计租金', value: 'estimated_rent' }, { label: '实际费用', value: 'actual_rent' }, { label: '状态', value: row => labels[row.status] }], '租赁订单.csv') }
</script>

<template>
  <div class="module-overview order-overview" aria-label="订单运营统计"><div class="order-metric order-metric--total"><strong>{{ state.orders.length }}</strong><span>全部订单</span></div><div class="order-metric order-metric--pickup"><strong>{{ state.orders.filter(item => item.status === 'RESERVED').length }}</strong><span>待取车</span></div><div class="order-metric order-metric--active"><strong>{{ state.orders.filter(item => item.status === 'ACTIVE').length }}</strong><span>租赁中</span></div><div class="order-metric order-metric--settlement"><strong>{{ state.orders.filter(item => item.status === 'RETURNED').length }}</strong><span>待结算</span></div><el-button type="primary" :icon="Plus" @click="create()">新建订单</el-button></div>
  <section class="panel listing-panel order-listing"><div class="filter-bar"><el-input v-model="query.search" placeholder="搜索订单号、客户、车牌" :prefix-icon="Search" clearable class="search-input"/><el-select v-model="query.status" placeholder="全部订单状态" clearable><el-option v-for="status in ['RESERVED', 'ACTIVE', 'RETURNED', 'COMPLETED', 'CANCELLED']" :key="status" :label="labels[status]" :value="status"/></el-select><div class="filter-spacer"></div><el-button :icon="Download" @click="exportData">导出订单</el-button></div><div v-if="query.scope" class="order-scope-note"><span>{{ { 'pickup-today': '今日待取车', 'return-today': '今日待还车', overdue: '逾期未还' }[query.scope] }} · 来自工作台</span><el-button link type="primary" @click="query.scope = ''; router.replace({ path: '/orders', query: { ...route.query, scope: undefined } })">查看全部订单</el-button></div><div class="listing-caption"><span>租赁业务记录 <small>{{ filtered.length }} 笔</small></span><span>预约 → 交车 → 还车 → 结算</span></div><el-table :data="filtered.slice((page - 1) * 10, page * 10)"><el-table-column label="订单 / 客户" min-width="190"><template #default="{ row }"><strong class="cell-title">{{ row.order_no }}</strong><small class="cell-sub">{{ customer(row.customer_id).name }}</small></template></el-table-column><el-table-column label="车辆" min-width="245"><template #default="{ row }"><div class="order-vehicle-cell"><VehicleThumbnail :vehicle="vehicle(row.vehicle_id)"/><div><strong class="cell-title">{{ vehicle(row.vehicle_id).brand }} {{ vehicle(row.vehicle_id).model }}</strong><small class="cell-sub">{{ vehicle(row.vehicle_id).plate }}</small></div></div></template></el-table-column><el-table-column label="计划租期" min-width="155"><template #default="{ row }"><span>{{ dateText(row.planned_start) }}</span><small class="cell-sub">至 {{ dateText(row.planned_end) }}</small></template></el-table-column><el-table-column label="租金 / 押金" min-width="135"><template #default="{ row }">¥{{ money(row.actual_rent ?? row.estimated_rent) }}<small class="cell-sub">押金 ¥{{ money(row.deposit) }}</small></template></el-table-column><el-table-column label="状态" width="115"><template #default="{ row }"><StatusTag :value="row.status"/><small v-if="overdue(row)" class="cell-sub text-danger">已逾期，请联系客户</small></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="detailId = row.id">查看 / 办理</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{ filtered.length }} 笔订单</span><el-pagination v-model:current-page="page" :total="filtered.length" :page-size="10" layout="prev, pager, next"/></div></section>
  <el-dialog v-model="open" :title="editId ? '修改租赁预约' : '新建租赁订单'" width="820px" :close-on-click-modal="false" destroy-on-close><el-alert title="先选择租期，再选择车辆。系统会校验资格、时间冲突和车辆状态。" type="info" :closable="false" show-icon/><el-form ref="formRef" :model="form" :rules="formRules" label-position="top" class="form-grid order-form"><el-form-item label="计划取车时间" prop="planned_start"><el-date-picker v-model="form.planned_start" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="计划还车时间" prop="planned_end"><el-date-picker v-model="form.planned_end" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="租赁客户" prop="customer_id"><el-select v-model="form.customer_id" filterable placeholder="选择客户" :disabled="!!editId"><el-option v-for="item in state.customers" :key="item.id" :label="item.name + (item.restricted ? '（限制租赁）' : '')" :value="item.id" :disabled="item.restricted"/></el-select></el-form-item><el-form-item label="租赁车辆" prop="vehicle_id"><el-select v-model="form.vehicle_id" filterable placeholder="选择可租车辆" popper-class="order-vehicle-options" :disabled="!!editId" @change="carChanged"><el-option v-for="item in state.vehicles" :key="item.id" :label="item.plate + ' · ' + item.model + (canBook(item) ? '' : '（不可租）')" :aria-label="item.plate + ' · ' + item.model + (canBook(item) ? '' : '（不可租）')" :value="item.id" :disabled="!canBook(item)"><div class="order-vehicle-option"><VehicleThumbnail :vehicle="item"/><div><strong>{{ item.brand }} {{ item.model }}</strong><small>{{ item.plate }}{{ canBook(item) ? '' : ' · 不可租' }}</small></div></div></el-option></el-select></el-form-item><el-form-item label="取车门店" prop="pickup_branch"><el-select v-model="form.pickup_branch" disabled><el-option v-for="item in state.branches" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="计划还车门店" prop="return_branch"><el-select v-model="form.return_branch"><el-option v-for="item in state.branches" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="计费方式" prop="billing_mode"><el-select v-model="form.billing_mode"><el-option v-for="mode in ['DAILY', 'MILEAGE', 'MONTHLY']" :key="mode" :label="labels[mode]" :value="mode"/></el-select></el-form-item><el-form-item label="预计行驶里程（km）" prop="expected_mileage"><el-input-number v-model="form.expected_mileage" :min="0" :max="1000000" controls-position="right"/></el-form-item></el-form><div v-if="quote" class="quote-strip"><div><span>预计租金</span><strong>¥{{ money(quote.rent) }}</strong><small>{{ quote.formula }}</small></div><div><span>应收押金</span><strong>¥{{ money(quote.deposit) }}</strong><small>押金不计入租赁收入</small></div><span class="soft-label">以实际归还结算为准</span></div><el-alert v-else-if="quoteError" :title="quoteError" type="warning" :closable="false"/><template #footer><el-button @click="open = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!quote" @click="save">确认{{ editId ? '修改' : '创建' }}订单</el-button></template></el-dialog>
  <el-drawer :model-value="!!detail" @close="detailId = null" title="租赁订单详情" size="680px"><template v-if="detail"><div class="order-detail-heading"><div><h2>{{ detail.order_no }}</h2></div><StatusTag :value="detail.status"/></div><el-alert v-if="overdue(detail)" title="该车辆已逾期未还，请及时联系客户。" type="warning" :closable="false"/><div class="order-detail-person"><div><small>租赁客户</small><strong>{{ customer(detail.customer_id).name }}</strong></div><el-icon><ArrowRight/></el-icon><div class="order-detail-vehicle"><VehicleThumbnail :vehicle="vehicle(detail.vehicle_id)"/><div><small>租赁车辆</small><strong>{{ vehicle(detail.vehicle_id).brand }} {{ vehicle(detail.vehicle_id).model }}</strong><span>{{ vehicle(detail.vehicle_id).plate }}</span></div></div></div><el-descriptions :column="2" border><el-descriptions-item label="计划取车">{{ dateText(detail.planned_start) }}</el-descriptions-item><el-descriptions-item label="计划还车">{{ dateText(detail.planned_end) }}</el-descriptions-item><el-descriptions-item label="实际取车">{{ dateText(detail.actual_start) }}</el-descriptions-item><el-descriptions-item label="实际还车">{{ dateText(detail.actual_end) }}</el-descriptions-item><el-descriptions-item label="取车门店">{{ branch(detail.pickup_branch).name }}</el-descriptions-item><el-descriptions-item label="还车门店">{{ branch(detail.return_branch).name }}</el-descriptions-item><el-descriptions-item label="取车里程">{{ detail.start_mileage ?? '—' }} km</el-descriptions-item><el-descriptions-item label="还车里程">{{ detail.end_mileage ?? '—' }} km</el-descriptions-item><el-descriptions-item label="计费方式">{{ labels[detail.billing_mode] }}</el-descriptions-item><el-descriptions-item label="应收押金">¥{{ money(detail.deposit) }}</el-descriptions-item><el-descriptions-item label="交车车况" :span="2">{{ detail.pickup_condition || '未交车' }}</el-descriptions-item><el-descriptions-item label="还车车况" :span="2">{{ detail.return_condition || '未还车' }}</el-descriptions-item></el-descriptions><div class="drawer-actions"><template v-if="detail.status === 'RESERVED'"><el-button type="primary" :loading="busy" @click="act('collect')">登记收款</el-button><el-button type="primary" plain :loading="busy" @click="act('pickup')">办理交车</el-button><el-button @click="create(detail)">修改预约</el-button><el-button type="danger" plain :loading="busy" @click="terminal('cancel')">取消订单</el-button></template><template v-if="detail.status === 'ACTIVE'"><el-button type="primary" @click="act('return')">办理还车</el-button><el-button @click="act('collect')">登记预收款</el-button></template><el-button v-if="detail.status === 'RETURNED'" type="primary" :loading="busy" @click="terminal('settle')">确认收退款并结算</el-button></div><h3 class="section-title">费用明细</h3><div class="financial-lines"><div><span>预计租金</span><strong>¥{{ money(detail.estimated_rent) }}</strong></div><div><span>附加费用</span><strong>¥{{ money(detail.extra_fee) }}</strong></div><div><span>优惠金额</span><strong>− ¥{{ money(detail.discount) }}</strong></div><div v-if="detail.fee_notes"><span>费用说明</span><span>{{ detail.fee_notes }}</span></div><div><span>实际费用</span><strong>{{ detail.actual_rent === null || detail.actual_rent === undefined ? '待还车核算' : '¥' + money(detail.actual_rent) }}</strong></div><div><span>净已收款（含押金）</span><strong>¥{{ money(netPaid(detail.id)) }}</strong></div><div v-if="detail.status === 'RETURNED'" class="total-line"><span>{{ Number(detail.actual_rent) - netPaid(detail.id) >= 0 ? '待补收' : '待退款' }}</span><strong>¥{{ money(Math.abs(Number(detail.actual_rent) - netPaid(detail.id))) }}</strong></div></div><h3 class="section-title">收退款记录</h3><el-table :data="payments(detail.id)"><el-table-column label="类型"><template #default="{ row }">{{ labels[row.kind] }}</template></el-table-column><el-table-column label="金额"><template #default="{ row }"><span :class="row.direction === 'IN' ? 'text-green' : 'text-danger'">{{ row.direction === 'IN' ? '+' : '−' }} ¥{{ money(row.amount) }}</span></template></el-table-column><el-table-column label="时间" min-width="150"><template #default="{ row }">{{ dateText(row.created_at) }}</template></el-table-column><el-table-column prop="operator" label="操作人"/></el-table><p class="field-tip">金额均为线下登记。押金不计入收入，结算后净收款与实际费用一致。</p></template></el-drawer>
  <FormDialog v-model="actionOpen" :title="{ collect: '登记线下收款', pickup: '办理车辆交付', return: '办理车辆归还' }[actionType]" :fields="actionFields" :initial="actionInitial" :busy="busy" @submit="submitAction"/>
</template>
